    private final Store store;            // private: unreachable outside this class
    private final Policy policy;
    Vault(Store store, Policy policy) { this.store = store; this.policy = policy; }
    Record read(Subject who, Id id) {
        if (!policy.allows(who, id)) throw new AccessControlException("denied " + id);
        return store.get(id);             // the store reference never leaves
